'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import Webcam from 'react-webcam';
import { motion, AnimatePresence } from 'framer-motion';
import { Wifi, WifiOff, MessageSquare, BarChart, Sliders } from 'lucide-react';
import { useEmotionSocket } from '../hooks/useEmotionSocket';
import { emotionStyles, Emotion } from '../lib/emotionStyles';
import BreathingGuide from '../components/breathingGuide';

// --- QUOTES DATA ---
const quotes: Record<Emotion, { quote: string; author: string }[]> = {
  happy: [
    { quote: "The purpose of our lives is to be happy.", author: "Dalai Lama" },
    { quote: "Happiness is not something ready made. It comes from your own actions.", author: "Dalai Lama" },
  ],
  sad: [
    { quote: "Tears come from the heart and not from the brain.", author: "Leonardo da Vinci" },
    { quote: "Heavy hearts, like heavy clouds in the sky, are best relieved by the letting of a little water.", author: "Christopher Morley" },
  ],
  angry: [
    { quote: "For every minute you remain angry, you give up sixty seconds of peace of mind.", author: "Ralph Waldo Emerson" },
    { quote: "Anger is an acid that can do more harm to the vessel in which it is stored than to anything on which it is poured.", author: "Mark Twain" },
  ],
  fear: [
      { quote: "The brave man is not he who does not feel afraid, but he who conquers that fear.", author: "Nelson Mandela"},
      { quote: "He who is not everyday conquering some fear has not learned the secret of life.", author: "Ralph Waldo Emerson"},
  ],
  surprise: [
    { quote: "The best way to be boring is to leave nothing out.", author: "Voltaire" },
    { quote: "A wonderful fact to reflect upon, that every human creature is constituted to be that profound secret and mystery to every other.", author: "Charles Dickens" },
  ],
  neutral: [
    { quote: "The mind is everything. What you think you become.", author: "Buddha" },
    { quote: "To enjoy the glow of good health, you must exercise.", author: "Gene Tunney" },
  ],
  disgust: [
      { quote: "Disgust is the appropriate reaction to most of what is sold as food.", author: "Wendell Berry"},
      { quote: "Disgust is a survival instinct.", author: "Jaguar Wright"},
  ],
  calm: [
    { quote: "Calmness is the cradle of power.", author: "Josiah Gilbert Holland" },
    { quote: "Peace is not absence of conflict, it is the ability to cope with it.", author: "Unknown" },
  ],
  default: [
    { quote: "Welcome to MindMorph. Let's begin the journey.", author: "MindMorph" },
    { quote: "Emotions are the colors of the soul.", author: "Unknown" },
  ],
};


export default function HomePage() {
  const webcamRef = useRef<Webcam>(null);
  const { emotion, isConnected, sendFrame } = useEmotionSocket('http://127.0.0.1:5000');
  const [showBreathingGuide, setShowBreathingGuide] = useState(false);

  const captureFrame = useCallback(() => {
    if (webcamRef.current) {
      const imageSrc = webcamRef.current.getScreenshot();
      if (imageSrc) {
        sendFrame(imageSrc);
      }
    }
  }, [sendFrame]);

  useEffect(() => {
    const interval = setInterval(() => {
      captureFrame();
    }, 500); // Send frame every 500ms
    return () => clearInterval(interval);
  }, [captureFrame]);

  // This effect watches the detected emotion and triggers the breathing guide
  useEffect(() => {
    if (emotion === 'angry' || emotion === 'fear') {
      setShowBreathingGuide(true);
    }
  }, [emotion]);

  const currentStyle = emotionStyles[emotion as Emotion] || emotionStyles.neutral;
  const currentQuotes = quotes[emotion as Emotion] || quotes.neutral;
  const [quoteIndex, setQuoteIndex] = useState(0);

  useEffect(() => {
    // Reset quote index when emotion changes to avoid out-of-bounds error
    setQuoteIndex(0); 
    
    const quoteInterval = setInterval(() => {
      setQuoteIndex((prevIndex) => (prevIndex + 1) % currentQuotes.length);
    }, 10000); // Change quote every 10 seconds
    return () => clearInterval(quoteInterval);
  }, [emotion, currentQuotes.length]);

  return (
    <>
      <main className="relative min-h-screen w-full overflow-hidden bg-gray-900 text-white transition-colors duration-[2000ms]">
        {/* Animated Aurora Background */}
        <motion.div
          className="absolute inset-0 z-0"
          animate={{
            background: `radial-gradient(ellipse at 40% 60%, ${currentStyle.auroraColors[0]} 0%, transparent 50%),
                         radial-gradient(ellipse at 60% 40%, ${currentStyle.auroraColors[1]} 0%, transparent 50%)`,
          }}
          transition={{ duration: 2.0, ease: 'easeInOut' }}
        />
        <div className="absolute inset-0 z-10 bg-black/30" />

        {/* Main Content */}
        <div className="relative z-20 flex h-screen flex-col items-center justify-between p-4 md:p-8">
          {/* Top Header */}
          <header className="flex w-full items-center justify-between">
            <h1 className="text-2xl font-bold">MindMorph</h1>
            <div className="flex items-center gap-4">
                <Sliders size={20} className="text-white/70 cursor-pointer" />
                <BarChart size={20} className="text-white/70 cursor-pointer" />
                <MessageSquare size={20} className="text-white/70 cursor-pointer" />
            </div>
          </header>

          {/* Center Content: Orb and Quote */}
          <div className="flex flex-col items-center gap-8">
            <motion.div
              className="relative flex h-48 w-48 items-center justify-center rounded-full text-center shadow-2xl"
              animate={{
                backgroundColor: currentStyle.orbColor,
                boxShadow: `0 0 40px 10px ${currentStyle.orbColor}`,
              }}
              transition={{ duration: 1.0, ease: 'easeInOut' }}
            >
                <motion.div
                    className="absolute h-full w-full rounded-full"
                    animate={{
                        scale: [1, 1.05, 1],
                        opacity: [0.5, 0.8, 0.5]
                    }}
                    transition={{
                        duration: 3,
                        repeat: Infinity,
                        ease: "easeInOut"
                    }}
                    style={{backgroundColor: currentStyle.orbColor}}
                />
              <span className="z-10 text-3xl font-bold capitalize">{emotion}</span>
            </motion.div>

            <div className="h-24 w-full max-w-2xl text-center">
               <AnimatePresence mode="wait">
                    <motion.div
                        key={quoteIndex}
                        initial={{ opacity: 0, y: -20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 20 }}
                        transition={{ duration: 0.8 }}
                        className="flex flex-col items-center"
                    >
                        <p className="text-xl italic">&ldquo;{currentQuotes[quoteIndex]?.quote}&rdquo;</p>
                        <p className="mt-2 text-sm text-white/60">- {currentQuotes[quoteIndex]?.author}</p>
                    </motion.div>
                </AnimatePresence>
            </div>
          </div>

          {/* Bottom Footer with Webcam */}
          <footer className="w-full">
            <div className="mx-auto w-full max-w-xs rounded-2xl border border-white/10 bg-white/5 p-2 backdrop-blur-lg">
              <div className="relative aspect-video w-full overflow-hidden rounded-lg">
                <Webcam
                  ref={webcamRef}
                  audio={false}
                  mirrored={true}
                  className="h-full w-full object-cover"
                  videoConstraints={{ width: 320, height: 180, facingMode: 'user' }}
                />
                <div className="absolute top-2 right-2 flex items-center gap-2 rounded-full bg-black/50 px-3 py-1 text-xs">
                  {isConnected ? (
                    <>
                      <Wifi size={14} className="text-green-400" />
                      <span>Connected</span>
                    </>
                  ) : (
                    <>
                      <WifiOff size={14} className="text-red-400" />
                      <span>Connecting...</span>
                    </>
                  )}
                </div>
              </div>
            </div>
          </footer>
        </div>
      </main>
      
      {/* Conditionally render the Breathing Guide */}
      <BreathingGuide
        isVisible={showBreathingGuide}
        onClose={() => setShowBreathingGuide(false)}
      />
    </>
  );
}

