import { useState, useEffect, useRef } from 'react';
import { io, Socket } from 'socket.io-client';

const SERVER_URL = 'http://127.0.0.1:5000'; // Your Flask backend URL

interface EmotionState {
  emotion: string;
  confidence: number;
}

export const useEmotionSocket = (url: string) => {
  const [emotion, setEmotion] = useState<string>('neutral');
  const [isConnected, setIsConnected] = useState(false);
  const socketRef = useRef<Socket | null>(null);

  useEffect(() => {
    // Initialize socket connection
    const socket = io(url, {
      transports: ['websocket'],
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });
    socketRef.current = socket;

    socket.on('connect', () => {
      console.log('Socket connected!');
      setIsConnected(true);
    });

    socket.on('disconnect', () => {
      console.log('Socket disconnected!');
      setIsConnected(false);
    });

    socket.on('emotion_update', (data: EmotionState) => {
      console.log('Emotion update received:', data);
      setEmotion(data.emotion);
    });

    socket.on('connect_error', (error) => {
        console.error('Connection error:', error);
    });

    // Cleanup on component unmount
    return () => {
      if (socketRef.current) {
        socketRef.current.disconnect();
      }
    };
  }, [url]);

  const sendFrame = (imageSrc: string) => {
    if (socketRef.current && socketRef.current.connected) {
      socketRef.current.emit('video_frame', imageSrc);
    }
  };

  return { emotion, isConnected, sendFrame };
};
